<#
.SYNOPSIS
GUI and packaged launcher for the Purview Teams PST to HTML converter.
.DESCRIPTION
This launcher embeds the converter script, writes it to a temporary file at runtime, and invokes it in STA mode.
It can run interactively with a WinForms UI or non-interactively for smoke tests and automation.
#>
[CmdletBinding()]
param(
    [string]$PstPath,
    [string]$OutputPath,
    [string]$LogPath,
    [string[]]$DefaultConversationParticipants = @(),
    [switch]$KeepPstAttached,
    [switch]$UseSampleData,
    [switch]$NoGui
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$script:EmbeddedCoreBase64 = ''

function Get-DefaultOutputDirectory {
    $downloads = Join-Path ([Environment]::GetFolderPath('UserProfile')) 'Downloads'
    if (Test-Path -LiteralPath $downloads) { return $downloads }
    return [Environment]::GetFolderPath('UserProfile')
}

function New-EmbeddedCoreScript {
    # Decode first so a corrupt/incomplete payload fails before any temp dir is created (no leak).
    try { $coreBytes = [Convert]::FromBase64String($script:EmbeddedCoreBase64) }
    catch { throw 'The packaged converter is corrupted or incomplete. Please reinstall the application.' }
    $tempRoot = Join-Path ([IO.Path]::GetTempPath()) ('PurviewTeamsPstToHtml_' + [guid]::NewGuid().ToString('N'))
    [System.IO.Directory]::CreateDirectory($tempRoot) | Out-Null
    $corePath = Join-Path $tempRoot 'Convert-PurviewTeamsPstToHtml.ps1'
    [IO.File]::WriteAllBytes($corePath, $coreBytes)
    # Read the file back and confirm it matches what we decoded (guards against on-disk
    # tampering or a partial write between here and launch). Mismatch => clean up, no leak.
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $expectedHash = [BitConverter]::ToString($sha.ComputeHash($coreBytes))
        $actualHash = [BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($corePath)))
    }
    finally { $sha.Dispose() }
    if ($expectedHash -ne $actualHash) {
        Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
        throw 'The packaged converter failed an integrity check. Please reinstall the application.'
    }
    return $corePath
}

function ConvertTo-ArgumentList {
    param(
        [string]$CorePath,
        [string]$PstPath,
        [string]$OutputPath,
        [string]$LogPath,
        [string[]]$DefaultConversationParticipants,
        [switch]$KeepPstAttached,
        [switch]$UseSampleData,
        [string]$RunId
    )

    $args = [System.Collections.Generic.List[string]]::new()
    $args.Add('-Sta')
    $args.Add('-NoProfile')
    $args.Add('-ExecutionPolicy')
    $args.Add('Bypass')
    $args.Add('-File')
    $args.Add($CorePath)
    $args.Add('-NoPrompt')

    if ($UseSampleData) { $args.Add('-UseSampleData') }
    elseif (-not [string]::IsNullOrWhiteSpace($PstPath)) { $args.Add('-PstPath'); $args.Add($PstPath) }

    if (-not [string]::IsNullOrWhiteSpace($OutputPath)) { $args.Add('-OutputPath'); $args.Add($OutputPath) }
    if (-not [string]::IsNullOrWhiteSpace($LogPath)) { $args.Add('-LogPath'); $args.Add($LogPath) }
    if ($KeepPstAttached) { $args.Add('-KeepPstAttached') }
    if (-not [string]::IsNullOrWhiteSpace($RunId)) { $args.Add('-RunId'); $args.Add($RunId) }
    foreach ($participant in @($DefaultConversationParticipants)) {
        if (-not [string]::IsNullOrWhiteSpace($participant)) {
            $args.Add('-DefaultConversationParticipants')
            $args.Add($participant.Trim())
        }
    }
    return $args.ToArray()
}

function ConvertTo-NativeArgumentString {
    param([string[]]$Argument)
    $quoted = foreach ($arg in @($Argument)) {
        if ($null -eq $arg) { '""'; continue }
        if ($arg -notmatch '[\s"]') { $arg; continue }
        '"' + ($arg -replace '([\\]*)"', '$1$1\"' -replace '([\\]+)$', '$1$1') + '"'
    }
    return ($quoted -join ' ')
}

function Resolve-PowerShell7Path {
    $cmd = Get-Command pwsh -ErrorAction SilentlyContinue
    $candidateProperties = @('Source','Path','Definition')
    foreach ($property in $candidateProperties) {
        if ($cmd -and ($cmd.PSObject.Properties.Name -contains $property)) {
            $candidate = [string]$cmd.$property
            if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
                return $candidate
            }
        }
    }

    $standardPaths = @(
        (Join-Path $env:ProgramFiles 'PowerShell\7\pwsh.exe'),
        (Join-Path ${env:ProgramFiles(x86)} 'PowerShell\7\pwsh.exe')
    )
    foreach ($candidate in $standardPaths) {
        if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
            return $candidate
        }
    }

    throw 'PowerShell 7 is required for this converter, but it was not found on this computer. Install PowerShell 7 from Microsoft, then run the converter again.'
}

function Invoke-EmbeddedConversion {
    param(
        [string]$PstPath,
        [string]$OutputPath,
        [string]$LogPath,
        [string[]]$DefaultConversationParticipants = @(),
        [switch]$KeepPstAttached,
        [switch]$UseSampleData,
        [scriptblock]$OnProgress
    )

    $corePath = New-EmbeddedCoreScript
    try {
        $pwsh = Resolve-PowerShell7Path

        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = $pwsh
        $childArgs = ConvertTo-ArgumentList -CorePath $corePath -PstPath $PstPath -OutputPath $OutputPath -LogPath $LogPath -DefaultConversationParticipants $DefaultConversationParticipants -KeepPstAttached:$KeepPstAttached -UseSampleData:$UseSampleData
        $psi.Arguments = ConvertTo-NativeArgumentString -Argument $childArgs
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true

        $stdoutBuilder = [System.Text.StringBuilder]::new()
        $proc = [System.Diagnostics.Process]::Start($psi)
        # Drain stderr concurrently so a full stderr pipe buffer can't deadlock the
        # synchronous stdout read below. ReadToEndAsync (StreamReader, .NET 4.5+) runs
        # the stderr read on the thread pool without a PowerShell event handler.
        $stderrTask = $proc.StandardError.ReadToEndAsync()
        while (-not $proc.StandardOutput.EndOfStream) {
            $line = $proc.StandardOutput.ReadLine()
            [void]$stdoutBuilder.AppendLine($line)
            if ($line -like 'CONVERSION_PROGRESS|*' -and $OnProgress) {
                & $OnProgress $line
            }
        }
        $stderr = $stderrTask.Result
        $proc.WaitForExit()
        $stdout = $stdoutBuilder.ToString()

        [pscustomobject]@{
            ExitCode = $proc.ExitCode
            StdOut = $stdout
            StdErr = $stderr
            ResultLine = (($stdout -split "`r?`n") | Where-Object { $_ -like 'CONVERSION_RESULT|*' } | Select-Object -Last 1)
        }
    }
    finally {
        if ($corePath -and (Test-Path -LiteralPath $corePath)) {
            $tempDir = Split-Path -Path $corePath -Parent
            Remove-Item -LiteralPath $tempDir -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}
# --- Child process lifetime: Win32 Job Object + tree kill -------------------------------
# The launcher holds ONE kill-on-close Job Object for its whole lifetime. The child pwsh is
# assigned to it, so if the launcher process is hard-killed the OS closes the handle and reaps
# the child (and any descendants it spawned). Explicit stop still uses taskkill /T for an
# immediate tree kill; the two mechanisms are complementary.
$script:JobObjectSource = @'
using System;
using System.Runtime.InteropServices;

public static class PurviewJobNative
{
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern IntPtr CreateJobObject(IntPtr lpJobAttributes, string lpName);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool SetInformationJobObject(IntPtr hJob, int JobObjectInfoClass, IntPtr lpJobObjectInfo, uint cbJobObjectInfoLength);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool AssignProcessToJobObject(IntPtr hJob, IntPtr hProcess);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool CloseHandle(IntPtr hObject);

    [StructLayout(LayoutKind.Sequential)]
    public struct JOBOBJECT_BASIC_LIMIT_INFORMATION
    {
        public long PerProcessUserTimeLimit;
        public long PerJobUserTimeLimit;
        public uint LimitFlags;
        public UIntPtr MinimumWorkingSetSize;
        public UIntPtr MaximumWorkingSetSize;
        public uint ActiveProcessLimit;
        public UIntPtr Affinity;
        public uint PriorityClass;
        public uint SchedulingClass;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct IO_COUNTERS
    {
        public ulong ReadOperationCount;
        public ulong WriteOperationCount;
        public ulong OtherOperationCount;
        public ulong ReadTransferCount;
        public ulong WriteTransferCount;
        public ulong OtherTransferCount;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct JOBOBJECT_EXTENDED_LIMIT_INFORMATION
    {
        public JOBOBJECT_BASIC_LIMIT_INFORMATION BasicLimitInformation;
        public IO_COUNTERS IoInfo;
        public UIntPtr ProcessMemoryLimit;
        public UIntPtr JobMemoryLimit;
        public UIntPtr PeakProcessMemoryUsed;
        public UIntPtr PeakJobMemoryUsed;
    }

    public const int JobObjectExtendedLimitInformation = 9;
    public const uint JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE = 0x2000;

    // Marshaling JOBOBJECT_EXTENDED_LIMIT_INFORMATION by hand from PowerShell 5.1 is
    // error-prone, so create + configure the kill-on-close job here and hand back the handle.
    public static IntPtr CreateKillOnCloseJob()
    {
        IntPtr hJob = CreateJobObject(IntPtr.Zero, null);
        if (hJob == IntPtr.Zero) { return IntPtr.Zero; }

        JOBOBJECT_EXTENDED_LIMIT_INFORMATION info = new JOBOBJECT_EXTENDED_LIMIT_INFORMATION();
        info.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;

        int length = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
        IntPtr ptr = Marshal.AllocHGlobal(length);
        try
        {
            Marshal.StructureToPtr(info, ptr, false);
            if (!SetInformationJobObject(hJob, JobObjectExtendedLimitInformation, ptr, (uint)length))
            {
                CloseHandle(hJob);
                return IntPtr.Zero;
            }
        }
        finally
        {
            Marshal.FreeHGlobal(ptr);
        }
        return hJob;
    }
}
'@

$script:launcherJobHandle = [IntPtr]::Zero
$script:launcherJobUnavailable = $false

function Initialize-LauncherJobObject {
    # Lazily creates the one launcher-lifetime kill-on-close Job Object. Returns its handle,
    # or [IntPtr]::Zero if the type/handle could not be created. The handle is intentionally
    # never closed - the OS closes it when the launcher exits, which is what reaps the child.
    if ($script:launcherJobHandle -ne [IntPtr]::Zero) { return $script:launcherJobHandle }
    if ($script:launcherJobUnavailable) { return [IntPtr]::Zero }
    try {
        if (-not ([System.Management.Automation.PSTypeName]'PurviewJobNative').Type) {
            Add-Type -TypeDefinition $script:JobObjectSource -Language CSharp
        }
        $handle = [PurviewJobNative]::CreateKillOnCloseJob()
        if ($handle -eq [IntPtr]::Zero) { $script:launcherJobUnavailable = $true; return [IntPtr]::Zero }
        $script:launcherJobHandle = $handle
        return $handle
    }
    catch {
        $script:launcherJobUnavailable = $true
        return [IntPtr]::Zero
    }
}

function Add-ProcessToLauncherJob {
    # Assigns a running process to the launcher job. A failure here must NOT abort the
    # conversion - explicit stop still relies on Stop-ProcessTree.
    param([Parameter(Mandatory = $true)][System.Diagnostics.Process]$Process)
    try {
        $handle = Initialize-LauncherJobObject
        if ($handle -eq [IntPtr]::Zero) { return $false }
        return [PurviewJobNative]::AssignProcessToJobObject($handle, $Process.Handle)
    }
    catch { return $false }
}

function Stop-ProcessTree {
    # Terminates a child process AND its descendants. .NET Framework's Process.Kill() has no
    # tree overload, so grandchildren (a pwsh that spawned more, Outlook COM helpers) would be
    # orphaned. taskkill /T /F kills the whole tree; fall back to Kill() if taskkill can't run.
    # Never throws - safe to call from teardown/FormClosing paths.
    param([AllowNull()][System.Diagnostics.Process]$Process)
    if ($null -eq $Process) { return }
    $procId = -1
    try {
        if ($Process.HasExited) { return }
        $procId = $Process.Id
    }
    catch { return }
    if ($procId -le 0) { return }

    $treeKilled = $false
    try {
        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = 'taskkill.exe'
        $psi.Arguments = "/PID $procId /T /F"
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $killer = [System.Diagnostics.Process]::Start($psi)
        if ($null -ne $killer) {
            [void]$killer.WaitForExit(5000)
            $treeKilled = $true
        }
    }
    catch { $treeKilled = $false }

    if (-not $treeKilled) {
        try { if (-not $Process.HasExited) { $Process.Kill() } } catch { }
    }
}

function Start-EmbeddedConversionProcess {
    param(
        [string]$PstPath,
        [string]$OutputPath,
        [string]$LogPath,
        [string[]]$DefaultConversationParticipants = @(),
        [switch]$KeepPstAttached,
        [switch]$UseSampleData,
        [string]$RunId
    )

    $corePath = New-EmbeddedCoreScript
    $proc = $null
    $subscription = $null
    try {
        $pwsh = Resolve-PowerShell7Path

        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = $pwsh
        $childArgs = ConvertTo-ArgumentList -CorePath $corePath -PstPath $PstPath -OutputPath $OutputPath -LogPath $LogPath -DefaultConversationParticipants $DefaultConversationParticipants -KeepPstAttached:$KeepPstAttached -UseSampleData:$UseSampleData -RunId $RunId
        $psi.Arguments = ConvertTo-NativeArgumentString -Argument $childArgs
        $psi.UseShellExecute = $false
        # Redirect stdout so the run-ID-tagged progress/stage lines can drive the GUI.
        # Stderr stays un-redirected; fatal-error detail is still read from the log file.
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $false
        $psi.CreateNoWindow = $true

        # Thread-safe hand-off: the OutputDataReceived handler runs on a non-UI thread and
        # MUST NOT touch WinForms controls; it only enqueues raw stdout lines. The WinForms
        # timer drains this queue on the UI thread. Verified in PS 5.1 that a
        # Register-ObjectEvent -Action enqueue fires during a modal ShowDialog loop, whereas a
        # raw add_OutputDataReceived scriptblock delegate crashes the process.
        $queue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
        $proc = [System.Diagnostics.Process]::new()
        $proc.StartInfo = $psi
        $subscription = Register-ObjectEvent -InputObject $proc -EventName OutputDataReceived -MessageData $queue -Action {
            if ($null -ne $EventArgs.Data) { $Event.MessageData.Enqueue($EventArgs.Data) }
        }
        [void]$proc.Start()
        # Bind the child to the launcher job before it spawns descendants so KILL_ON_JOB_CLOSE
        # reaps the whole tree if the launcher dies. Best-effort: never abort the conversion.
        [void](Add-ProcessToLauncherJob -Process $proc)
        $proc.BeginOutputReadLine()

        [pscustomobject]@{
            Process = $proc
            CorePath = $corePath
            TempDir = Split-Path -Path $corePath -Parent
            OutputQueue = $queue
            OutputSubscription = $subscription
        }
    }
    catch {
        # If Start()/BeginOutputReadLine() (or anything after the subscription) threw, the
        # event subscription and process are already live - tear them down so repeated failed
        # clicks can't accumulate orphaned subscribers.
        if ($subscription) {
            Stop-ConversionOutputReader -Conversion ([pscustomobject]@{ Process = $proc; OutputSubscription = $subscription })
        }
        if ($proc) { try { $proc.Dispose() } catch { } }
        if ($corePath -and (Test-Path -LiteralPath $corePath)) {
            $tempDir = Split-Path -Path $corePath -Parent
            Remove-Item -LiteralPath $tempDir -Recurse -Force -ErrorAction SilentlyContinue
        }
        throw
    }
}


function ConvertFrom-ProgressStdoutLine {
    # Pure, side-effect-free mapper from a core stdout line to a GUI progress step.
    # Returns $null for anything that is NOT an applicable current-run progress/stage line:
    #   - not a CONVERSION_PROGRESS / CONVERSION_STAGE machine line
    #   - a line whose RunId != ExpectedRunId (foreign run)
    #   - a line with no RunId while an ExpectedRunId is set (stale/pre-RunId line)
    #   - a malformed line (never throws)
    # Otherwise returns [pscustomobject]@{ Percent = <int>; Status = <string> }.
    # Percent bands mirror the timer's historical mapping: collected 15-58,
    # FinishedReading 60, PreparingReport 62, WritingReport 66 (start) / 68-91 (progress),
    # Finalizing 92, Detaching 94, ReportWritten 96.
    param(
        [AllowNull()][string]$Line,
        [AllowNull()][string]$ExpectedRunId
    )

    if ([string]::IsNullOrWhiteSpace($Line)) { return $null }
    # No active run id means nothing is applicable; also stops an untagged line from matching
    # an empty expected id on control reuse.
    if ([string]::IsNullOrEmpty($ExpectedRunId)) { return $null }
    if ($Line -notmatch '^CONVERSION_(PROGRESS|STAGE)\|') { return $null }

    $fields = @{}
    foreach ($part in ($Line -split '\|')) {
        $idx = $part.IndexOf('=')
        if ($idx -gt 0) { $fields[$part.Substring(0, $idx)] = $part.Substring($idx + 1) }
    }

    # RunId gating: only current-run lines are applicable. A missing RunId yields ''
    # which will not equal a non-empty ExpectedRunId, so stale/foreign lines are ignored.
    $lineRunId = if ($fields.ContainsKey('RunId')) { [string]$fields['RunId'] } else { '' }
    if ($lineRunId -ne [string]$ExpectedRunId) { return $null }

    if ($Line -match '^CONVERSION_PROGRESS\|') {
        $collected = 0
        if ($fields.ContainsKey('ItemsExported')) { [void][int]::TryParse([string]$fields['ItemsExported'], [ref]$collected) }
        $percent = [Math]::Min(58, 15 + [int][Math]::Ceiling($collected / 400))
        $status = "Reading PST... collected $collected"
        if ($fields.ContainsKey('FolderPath') -and -not [string]::IsNullOrWhiteSpace([string]$fields['FolderPath'])) {
            $status += "; folder: $([string]$fields['FolderPath'])"
        }
        return [pscustomobject]@{ Percent = $percent; Status = $status }
    }

    # CONVERSION_STAGE
    $stage = if ($fields.ContainsKey('Stage')) { [string]$fields['Stage'] } else { '' }
    switch ($stage) {
        'FinishedReading' { return [pscustomobject]@{ Percent = 60; Status = 'Finished reading PST. Preparing report...' } }
        'PreparingReport' { return [pscustomobject]@{ Percent = 62; Status = 'Preparing HTML report...' } }
        'WritingReport' {
            $written = 0; $total = 0
            if ($fields.ContainsKey('Written')) { [void][int]::TryParse([string]$fields['Written'], [ref]$written) }
            if ($fields.ContainsKey('Total')) { [void][int]::TryParse([string]$fields['Total'], [ref]$total) }
            if ($written -le 0) {
                return [pscustomobject]@{ Percent = 66; Status = 'Writing HTML report...' }
            }
            $total = [Math]::Max(1, $total)
            $percent = [Math]::Min(91, 68 + [int][Math]::Floor(($written / $total) * 23))
            return [pscustomobject]@{ Percent = $percent; Status = "Writing HTML report... $written of $total conversations" }
        }
        'Finalizing'   { return [pscustomobject]@{ Percent = 92; Status = 'Finalizing HTML report...' } }
        'Detaching'    { return [pscustomobject]@{ Percent = 94; Status = 'Detaching PST and cleaning up...' } }
        'ReportWritten' { return [pscustomobject]@{ Percent = 96; Status = 'Cleaning up...' } }
        default { return $null }
    }
}

function Stop-ConversionOutputReader {
    # Tears down the async stdout reader and its event subscription so no handler leaks
    # after a conversion completes or the window closes. Safe to call more than once.
    param([AllowNull()][object]$Conversion)
    if ($null -eq $Conversion) { return }
    try { if ($Conversion.Process) { $Conversion.Process.CancelOutputRead() } } catch { }
    if ($Conversion.PSObject.Properties.Name -contains 'OutputSubscription' -and $Conversion.OutputSubscription) {
        try { Unregister-Event -SourceIdentifier $Conversion.OutputSubscription.Name -ErrorAction SilentlyContinue } catch { }
        try { Remove-Job -Id $Conversion.OutputSubscription.Id -Force -ErrorAction SilentlyContinue } catch { }
    }
}

function ConvertFrom-ResultLine {
    param([AllowNull()][string]$ResultLine)
    $result = @{}
    if ([string]::IsNullOrWhiteSpace($ResultLine)) { return $result }
    foreach ($part in ($ResultLine -split '\|')) {
        if ($part -eq 'CONVERSION_RESULT') { continue }
        $idx = $part.IndexOf('=')
        if ($idx -gt 0) { $result[$part.Substring(0, $idx)] = $part.Substring($idx + 1) }
    }
    return $result
}

function Assert-OutlookAvailableForRealRun {
    param([switch]$UseSampleData)
    if ($UseSampleData) { return }
    $outlookType = [type]::GetTypeFromProgID('Outlook.Application')
    if ($null -eq $outlookType) {
        throw 'Microsoft Outlook is required for this converter, but Outlook is not installed or is not registered on this computer. Install and configure Microsoft Outlook, then run the converter again.'
    }
}

function Start-NoGuiMode {
    try {
        Assert-OutlookAvailableForRealRun -UseSampleData:$UseSampleData
        $result = Invoke-EmbeddedConversion -PstPath $PstPath -OutputPath $OutputPath -LogPath $LogPath -DefaultConversationParticipants $DefaultConversationParticipants -KeepPstAttached:$KeepPstAttached -UseSampleData:$UseSampleData
        if ($result.StdOut) { Write-Output $result.StdOut.TrimEnd() }
        # Surface child stderr without raising a terminating error, so stderr noise on a
        # successful (exit 0) run isn't turned into a failure. Success is decided strictly
        # by the child's ExitCode below.
        if ($result.StdErr) { [Console]::Error.WriteLine($result.StdErr.TrimEnd()) }
        if ($result.ExitCode -ne 0) { [Environment]::Exit([int]$result.ExitCode) }
    }
    catch {
        [Console]::Error.WriteLine($_.Exception.Message)
        [Environment]::Exit(1)
    }
}

function Start-GuiMode {
    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing
    [System.Windows.Forms.Application]::EnableVisualStyles()

    $missingPrograms = [System.Collections.Generic.List[string]]::new()
    try { [void](Resolve-PowerShell7Path) }
    catch { [void]$missingPrograms.Add($_.Exception.Message) }
    try { Assert-OutlookAvailableForRealRun -UseSampleData:$false }
    catch { [void]$missingPrograms.Add($_.Exception.Message) }
    if ($missingPrograms.Count -gt 0) {
        [System.Windows.Forms.MessageBox]::Show(($missingPrograms -join "`n`n"), 'Required program missing', 'OK', 'Error') | Out-Null
        return
    }

    $defaultDir = Get-DefaultOutputDirectory
    $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'

    $form = [System.Windows.Forms.Form]::new()
    $form.Text = 'Purview Teams PST to HTML Converter'
    $form.Size = [System.Drawing.Size]::new(820, 620)
    $form.StartPosition = 'CenterScreen'
    $form.MinimumSize = [System.Drawing.Size]::new(760, 560)
    $font = [System.Drawing.Font]::new('Segoe UI', 9)
    $form.Font = $font

    $title = [System.Windows.Forms.Label]::new()
    $title.Text = 'Purview Teams PST to HTML Converter'
    $title.Font = [System.Drawing.Font]::new('Segoe UI', 14, [System.Drawing.FontStyle]::Bold)
    $title.AutoSize = $true
    $title.Location = [System.Drawing.Point]::new(16, 14)
    $form.Controls.Add($title)

    $subtitle = [System.Windows.Forms.Label]::new()
    $subtitle.Text = 'Converts a Microsoft Purview Teams PST export into a local, filterable HTML review report.'
    $subtitle.AutoSize = $true
    $subtitle.Location = [System.Drawing.Point]::new(18, 45)
    $form.Controls.Add($subtitle)

    function Add-Label($text, $x, $y) {
        $label = [System.Windows.Forms.Label]::new()
        $label.Text = $text
        $label.Location = [System.Drawing.Point]::new($x, $y)
        $label.Size = [System.Drawing.Size]::new(150, 22)
        $form.Controls.Add($label)
        return $label
    }
    function Add-TextBox($x, $y, $w) {
        $box = [System.Windows.Forms.TextBox]::new()
        $box.Location = [System.Drawing.Point]::new($x, $y)
        $box.Size = [System.Drawing.Size]::new($w, 24)
        $form.Controls.Add($box)
        return $box
    }
    function Add-Button($text, $x, $y, $w) {
        $button = [System.Windows.Forms.Button]::new()
        $button.Text = $text
        $button.Location = [System.Drawing.Point]::new($x, $y)
        $button.Size = [System.Drawing.Size]::new($w, 28)
        $form.Controls.Add($button)
        return $button
    }

    function Get-SafeOutputBaseNameFromPstPath([string]$Path) {
        if ([string]::IsNullOrWhiteSpace($Path)) { return '' }
        try { $baseName = [IO.Path]::GetFileNameWithoutExtension($Path.Trim('"').Trim("'")) }
        catch { $baseName = '' }
        if ([string]::IsNullOrWhiteSpace($baseName)) { return '' }
        $atIndex = $baseName.IndexOf('@')
        if ($atIndex -gt 0) { $baseName = $baseName.Substring(0, $atIndex) }
        foreach ($char in [IO.Path]::GetInvalidFileNameChars()) { $baseName = $baseName.Replace([string]$char, ' ') }
        $baseName = (($baseName -replace '\s+', ' ').Trim())
        if ([string]::IsNullOrWhiteSpace($baseName)) { return '' }
        return "$baseName Teams Messages"
    }

    function Update-OutputPathsFromPstPath {
        param([bool]$Force = $false)
        if (-not $Force -and -not $script:autoNameOutputFromPst) { return }
        $baseName = Get-SafeOutputBaseNameFromPstPath -Path $pstBox.Text
        if ([string]::IsNullOrWhiteSpace($baseName)) { return }
        $outputBox.Text = Join-Path $defaultDir ($baseName + '.html')
        $logBox.Text = Join-Path $defaultDir ($baseName + '.log')
        $script:autoNameOutputFromPst = $true
    }

